import './Footer.css';

const Footer = () => {
  return (
    <footer className="footer">
      <div className="footer-content">
        <p>&copy; 2025 EarlyBirds Schools. All rights reserved.</p>
        <p>Contact us: info@school.com | +123 456 7890</p>
      </div>
    </footer>
  );
};

export default Footer;
